    } else {
      sendHtml(res, 404, 'Not found', '<h1>Page not found</h1>');
    }
  } catch (error) {
    console.error(error);
    if (!res.headersSent) sendHtml(res, 500, 'Error', '<h1>Something went wrong</h1>');
    else res.end();
  }
});
